def _sc_score(info: dict) -> int:
    s = 0
    rg = info.get("revenueGrowth") or 0
    if rg > 0.20: s += 20
    elif rg > 0.10: s += 12
    elif rg > 0.03: s += 6
    gm = info.get("grossMargins") or 0
    if gm > 0.60: s += 20
    elif gm > 0.40: s += 12
    elif gm > 0.25: s += 6
    om = info.get("operatingMargins") or 0
    if om > 0.25: s += 15
    elif om > 0.15: s += 9
    elif om > 0.05: s += 4
    fcf = info.get("freeCashflow") or 0
    mkt = info.get("marketCap") or 1
    fcy = fcf / mkt if mkt else 0
    if fcy > 0.05: s += 15
    elif fcy > 0.02: s += 8
    elif fcy > 0: s += 4
    roe = info.get("returnOnEquity") or 0
    if roe > 0.25: s += 15
    elif roe > 0.15: s += 9
    elif roe > 0.08: s += 4
    de = info.get("debtToEquity") or 0
    if de < 30: s += 10
    elif de < 80: s += 5
    if (info.get("trailingEps") or 0) > 0: s += 5
    return min(s, 100)

def _sc_fair_value(info: dict) -> float | None:
    eps    = info.get("trailingEps") or 0
    rg_pct = (info.get("revenueGrowth") or 0) * 100
    fcf    = info.get("freeCashflow") or 0
    shares = info.get("sharesOutstanding") or 0
    graham = eps * (8.5 + 2 * rg_pct) if (eps > 0 and 0 < rg_pct <= 50) else None
    fcf_fv = (fcf * 20) / shares if (fcf > 0 and shares > 0) else None
    if graham and fcf_fv:
        return round(graham * 0.4 + fcf_fv * 0.6, 2)
    return round(graham or fcf_fv, 2) if (graham or fcf_fv) else None

@st.cache_data(ttl=14400, show_spinner=False)
def load_screener_data() -> list[dict]:
    """Screent ~50 Qualitätstitel; gecacht für 4 Stunden."""
    results = []
    for tkr in _SCREENER_WATCHLIST:
        try:
            info  = yf.Ticker(tkr).info
            price = info.get("currentPrice") or info.get("regularMarketPrice")
            if not price:
                continue
            score = _sc_score(info)
            fv    = _sc_fair_value(info)
            if score >= 65 and fv and price < fv * 0.92:
                discount = (fv - price) / fv * 100
                results.append({
                    "ticker":   tkr,
                    "name":     (info.get("shortName") or tkr)[:28],
                    "price":    price,
                    "fv":       fv,
                    "discount": discount,
                    "score":    score,
                    "currency": info.get("currency", "USD"),
                    "sector":   info.get("sector", ""),
                })
        except Exception:
            pass
    results.sort(key=lambda x: x["score"] * x["discount"], reverse=True)
    return results[:8]


@st.cache_data(ttl=21600, show_spinner=False)
def _load_screener_universe() -> list[dict]:
    """Fetches metrics for ~90 quality stocks universe for the advanced screener (6h cache)."""
    _div_tickers = [k for k, v in _DIVIDEND_POOL.items() if isinstance(v, tuple)]
    _universe = list(dict.fromkeys(
        _SCREENER_WATCHLIST +
        list(_GROWTH_POOL.keys()) +
        list(_VALUE_POOL.keys()) +
        _div_tickers +
        list(_MIDCAP_POOL.keys())
    ))
    results = []
    for tkr in _universe:
        try:
            info  = yf.Ticker(tkr).info
            price = info.get("currentPrice") or info.get("regularMarketPrice") or 0
            if not price:
                continue
            mktcap = info.get("marketCap") or 0
            fcf    = info.get("freeCashflow") or 0
            gm     = (info.get("grossMargins") or 0) * 100
            om     = (info.get("operatingMargins") or 0) * 100
            nm     = (info.get("profitMargins") or 0) * 100
            roe    = (info.get("returnOnEquity") or 0) * 100
            roa    = (info.get("returnOnAssets") or 0) * 100
            rg     = (info.get("revenueGrowth") or 0) * 100
            dy     = (info.get("dividendYield") or 0) * 100
            de     = info.get("debtToEquity") or 0
            sec    = info.get("sector") or ""
            ind    = info.get("industry") or ""
            moat   = compute_moat(sec, ind, gm, roe, om, nm, rg, mktcap, de)
            rev    = info.get("totalRevenue") or 0
            fcf_m  = round(fcf / rev * 100, 1) if (fcf and rev > 0) else None
            r40    = round(rg + (fcf_m if fcf_m is not None else om), 1)
            _pe_t  = info.get("trailingPE")
            _pb_v  = info.get("priceToBook")
            _mos_g = round(((22.5 / (_pe_t * _pb_v)) ** 0.5 - 1) * 100, 1) if (_pe_t and _pe_t > 0 and _pb_v and _pb_v > 0) else None
            _qs    = _sc_score(info)
            _mos_q = round(_qs * 0.6 + max(0.0, min(100.0, (_mos_g if _mos_g is not None else -50.0) + 50.0)) * 0.4)
            _aup   = round(((info.get("targetMeanPrice") or price) / price - 1) * 100, 1) if price else 0.0
            results.append({
                "ticker":       tkr,
                "name":         (info.get("shortName") or info.get("longName") or tkr)[:32],
                "price":        round(price, 2),
                "currency":     info.get("currency", "USD"),
                "sector":       sec,
                "marketcap":    mktcap,
                "pe_fwd":       info.get("forwardPE"),
                "pe_trail":     _pe_t,
                "pb":           _pb_v,
                "rev_growth":   round(rg, 1),
                "gross_margin": round(gm, 1),
                "op_margin":    round(om, 1),
                "roe":          round(roe, 1),
                "roa":          round(roa, 1),
                "fcf_yield":    round(fcf / mktcap * 100, 1) if (fcf and mktcap > 0) else 0.0,
                "div_yield":    round(dy, 2),
                "payout":       round((info.get("payoutRatio") or 0) * 100, 1),
                "beta":         round(info.get("beta") or 1.0, 2),
                "debt_equity":  round(de, 1),
                "quality":      _qs,
                "moat_width":   moat.get("moat_width", "Kein Moat"),
                "moat_score":   moat.get("moat_score", 0),
                "analyst_up":   _aup,
                "fcf_margin":   fcf_m,
                "r40":          r40,
                "mos_graham":   _mos_g,
                "mos_q_score":  _mos_q,
            })
        except Exception:
            pass
    return sorted(results, key=lambda x: x["quality"], reverse=True)


